mapper.sql:
WHERE 1=1
AND u.id=#{userId}

AND EXISTS(SELECT 1 FROM sys_user_role ur JOIN sys_role r ON r.id=ur.role_id
    JOIN sys_role_menu rm ON rm.role_id=r.id WHERE ur.user_id=u.id AND rm.menu_id=#{menuId}
    AND r.status='ENABLED')
AND u.status=1 AND u.must_change_password=FALSE

mapper.select:
SELECT subject_id,id,code,name,status FROM (
    SELECT rm.menu_id AS subject_id,r.id,r.code,r.name,r.status,
      ROW_NUMBER() OVER(PARTITION BY rm.menu_id ORDER BY CASE WHEN r.status='ENABLED' THEN 0 ELSE 1 END,r.id) AS source_rank
    FROM sys_user_role ur JOIN sys_role r ON r.id=ur.role_id JOIN sys_role_menu rm ON rm.role_id=r.id
    WHERE ur.user_id=#{userId} AND rm.menu_id IN #{id}
) ranked WHERE source_rank <= 3 ORDER BY subject_id,source_rank

SELECT subject_id,id,code,name,status FROM (
    SELECT ur.user_id AS subject_id,r.id,r.code,r.name,r.status,
      ROW_NUMBER() OVER(PARTITION BY ur.user_id ORDER BY CASE WHEN r.status='ENABLED' THEN 0 ELSE 1 END,r.id) AS source_rank
    FROM sys_user_role ur JOIN sys_role r ON r.id=ur.role_id JOIN sys_role_menu rm ON rm.role_id=r.id
    WHERE rm.menu_id=#{menuId} AND ur.user_id IN #{id}
) ranked WHERE source_rank <= 3 ORDER BY subject_id,source_rank

